-- Opt-in real-engine smoke for the host adapter (stage.group.DefStageFunc).
-- Load from the startup macro before lib/Lplugin.lua. Creates only
-- userdata/spell_hot_reload_smoke/*; never edits mod/project files.
--
-- It exercises the whole path against the real engine: the production DoFile
-- hook runs the generated file (registering the stage group and the entry
-- point), the watcher promotes an edited copy to a stable candidate, and the
-- generic Driver + Host adapter replace the single entry point. The generated
-- wiring must not re-run, so the stage registration count stays constant.
local output_root = "userdata/spell_hot_reload_smoke"
local file_name = "StageReload_Boss.lua"
local group_name = "SpellHotReloadStage"
local stage_name = "SpellHotReloadStage@Smoke"
local finished = false

local function finish(ok, message)
    if finished then return end
    finished = true
    local text = (ok and "PASS " or "FAIL ") .. tostring(message)
    lstg.Log(ok and 2 or 4, "[SpellHotReload host engine smoke] " .. text)
    local f = assert(io.open(output_root .. "/result.txt", "wb"))
    f:write(text, "\n"); f:close()
    lstg.quit_flag = true
end

local function install()
    lstg.FileManager.CreateDirectory(output_root)
    local template = [=[-- Generated by LuaSTG Editor Sharp
__shr_stage.wiring = __shr_stage.wiring + 1
stage.group.New('menu', {}, "SpellHotReloadStage", { lifeleft = 7, power = 400, faith = 50000, bomb = 2 }, false)
stage.group.AddStage("SpellHotReloadStage", "SpellHotReloadStage@Smoke", {}, false)
stage.group.DefStageFunc("SpellHotReloadStage@Smoke", 'init', function(self)
    __shr_stage.version = SMOKE_VERSION
    __shr_stage.calls = __shr_stage.calls + 1
end)
]=]
    local function write_version(version)
        local f = assert(io.open(output_root .. "/" .. file_name, "wb"))
        f:write((template:gsub("SMOKE_VERSION", tostring(version))))
        f:close()
    end

    __shr_stage = { wiring = 0, calls = 0, version = 0 }
    write_version(1)
    -- The production DoFile hook must run the file and capture its source.
    lstg.DoFile(output_root .. "/" .. file_name)

    local live = require("SpellHotReload.View").plugin
    assert(live, "the plugin singleton is not initialized")
    local registry = live:GetRegistry()
    local original = assert(registry:GetSource(file_name), "the load hook did not capture the source")

    local group = assert(stage.stages[stage_name], "DefStageFunc did not register the stage entry point")
    local init = group.init
    assert(__shr_stage.wiring == 1, "generated wiring ran " .. tostring(__shr_stage.wiring) .. " time(s)")
    init()
    assert(__shr_stage.version == 1 and __shr_stage.calls == 1, "the v1 entry point did not run")
    __shr_stage.calls = 0

    local stage_count, group_count = 0, #stage.groups
    for _ in pairs(stage.stages) do stage_count = stage_count + 1 end

    local Watcher = require("SpellHotReload.Watcher")
    local PluginMod = require("SpellHotReload.Plugin")
    local Driver = require("SpellHotReload.Driver")
    local NodeRegistry = require("SpellHotReload.NodeRegistry")
    local Host = require("SpellHotReload.Host")

    local p = PluginMod.New()
    p._registry = registry
    p._activated, p._supported, p._sandbox_ok = true, true, true
    p._root = output_root
    p._watcher = Watcher.New({ root = output_root, store = p:GetStore(), quiet_frames = 3 })
    p._watcher:baseline()
    assert(p._watcher:Start())

    local adapters = NodeRegistry.New()
    assert(adapters:Register("host", Host))
    local driver = Driver.New({ adapters = adapters })

    write_version(2)

    local frames = 0
    local view = {}
    function view:getWindowName() return "SpellHotReload host engine smoke" end
    function view:getMenuGroupName() return "Tool" end
    function view:getEnable() return false end
    function view:setEnable() end
    function view:layout() end
    function view:update()
        if finished then return end
        local ok, err = xpcall(function()
            frames = frames + 1
            assert(frames < 1800, "timed out waiting for a stable candidate")
            p:Tick()
            local cand = p:GetStore():GetCandidate(file_name)
            if cand == nil or not cand.stable then return end

            -- Plan must not touch the running game.
            local run = assert(driver:Plan(file_name, cand.first_content,
                { previous = original, host_calls = Host.Callees }))
            assert(run.planned == 1,
                "expected exactly one planned host node, got " .. tostring(run.planned))
            assert(stage.stages[stage_name].init == init, "plan replaced the live definition")
            assert(__shr_stage.wiring == 1, "plan re-ran the generated wiring")

            local report = driver:Commit(run)
            assert(report.committed == 1, "commit did not apply the host node")
            local newinit = stage.stages[stage_name].init
            assert(newinit ~= init, "the entry point was not replaced")
            assert(group.init == newinit, "commit wrote a different table")
            newinit()
            assert(__shr_stage.version == 2, "the new definition did not run (version)")
            assert(__shr_stage.calls == 1, "the new definition did not run exactly once")

            local stage_count2 = 0
            for _ in pairs(stage.stages) do stage_count2 = stage_count2 + 1 end
            assert(stage_count2 == stage_count, "stage.stages gained a key")
            assert(#stage.groups == group_count, "stage.groups gained an entry")
            assert(__shr_stage.wiring == 1, "the generated wiring ran a second time")

            p:StopWatching()
            finish(true, "watcher candidate + DefStageFunc reload: entry point replaced, no duplicate registration")
        end, debug.traceback)
        if not ok then p:StopWatching(); finish(false, err) end
    end
    require("lib.Ldebug").addView("spellHotReload.hostEngineSmoke", view)
end

-- Chain the startup loader; register after the plugin manager exists.
local original_dofile = lstg.DoFile
lstg.DoFile = function(filename, ...)
    local result = original_dofile(filename, ...)
    if filename:gsub("\\", "/"):match("lib/Lplugin%.lua$") then
        lstg.plugin.RegisterEvent("afterMod", "spellHotReload.hostEngineSmoke", 1000, function()
            local ok, err = xpcall(install, debug.traceback)
            if not ok then finish(false, err) end
        end)
    end
    return result
end
